import {escapeHTML as e} from './math-ui.js';
import {numberText as f} from './visual-models.js';
const colors={orange:'#df6c24',blue:'#3c7293',green:'#497657',red:'#b83d37',paper:'#eee6d2'};
function lines(text,x,y,max=26,anchor='middle'){let words=String(text).split(/\s+/),parts=[],line='';for(let w of words){if((line+' '+w).length>max&&line){parts.push(line);line=w}else line+=(line?' ':'')+w}if(line)parts.push(line);return `<text x="${x}" y="${y}" text-anchor="${anchor}">${parts.map((s,i)=>`<tspan x="${x}" dy="${i?21:0}">${e(s)}</tspan>`).join('')}</text>`}
let svgSerial=0;
function svg(body,h,title){let arrow='vis-arrow-'+(++svgSerial);body=body.replaceAll('url(#vis-arrow)','url(#'+arrow+')');return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 ${h}" width="600" height="${h}" role="img" aria-label="${e(title)}"><title>${e(title)}</title><defs><marker id="${arrow}" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8" fill="context-stroke"/></marker></defs>${body}</svg>`}
export function renderScene(scene,title='Minh họa mạng'){if(!scene)return '';let body='',height=200;
if(scene.kind==='network'){let nodes=scene.nodes,coords=new Map(),circular=scene.edges.some(ed=>ed.selected!==undefined)||scene.nodes.every(n=>n.label.length<=12),count=nodes.length;height=scene.layout==='star'?430:circular?430:Math.ceil(count/2)*125+40;nodes.forEach((n,i)=>{let x,y;if(scene.layout==='star'){[x,y]=[[300,210],[300,55],[125,345],[475,345]][i]}else if(circular){let a=-Math.PI/2+2*Math.PI*i/count;x=300+205*Math.cos(a);y=210+150*Math.sin(a)}else{x=i%2?440:160;y=70+Math.floor(i/2)*125}coords.set(n.id,{x,y})});for(let ed of scene.edges){let a=coords.get(ed.a),b=coords.get(ed.b);if(!a||!b)continue;let dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy)||1,cut=circular?46:55,chosen=ed.selected||ed.active;body+=`<path d="M${a.x+dx/len*cut} ${a.y+dy/len*cut} L${b.x-dx/len*cut} ${b.y-dy/len*cut}" fill="none" stroke="${chosen?colors.green:'#849089'}" stroke-width="${chosen?5:2}" ${ed.directed===false?'':'marker-end="url(#vis-arrow)"'}/>`;if(ed.label)body+=`<rect x="${(a.x+b.x)/2-38}" y="${(a.y+b.y)/2-18}" width="76" height="25" fill="#fffaf0"/>`+lines(ed.label,(a.x+b.x)/2,(a.y+b.y)/2,20)}for(let n of nodes){let {x,y}=coords.get(n.id),active=scene.active?.includes(n.id),bad=scene.bad?.includes(n.id);body+=`<rect x="${x-(circular?75:112)}" y="${y-37}" width="${circular?150:224}" height="${n.detail?98:80}" rx="12" fill="${bad?'#fae4df':active?'#e2ecdd':'#fffaf0'}" stroke="${bad?colors.red:active?colors.green:'#92988a'}" stroke-width="${active||bad?4:2}"/>`+lines(n.label,x,y-12,circular?14:24)+ (n.detail?lines(n.detail,x,y+36,circular?18:26):'')}}
else if(scene.kind==='sequence'){let count=scene.actors.length,xx=i=>55+i*490/Math.max(1,count-1);let visible=scene.events.slice(-6),offset=scene.events.length-visible.length;height=105+visible.length*66;scene.actors.forEach((a,i)=>{body+=lines(a,xx(i),25,count>3?12:23)+`<path d="M${xx(i)} 65V${height-20}" stroke="#a3aaa0" stroke-dasharray="5 5"/>`});visible.forEach((ev,i)=>{let y=95+i*66,active=i+offset===scene.active,col=ev.lost?colors.red:active?colors.orange:'#72837a',a=xx(ev.from),b=xx(ev.to),end=ev.lost?(a+b)/2:b;body+=`<path d="M${a} ${y}L${end} ${y}" fill="none" stroke="${col}" stroke-width="${active?4:2}" ${ev.lost?'stroke-dasharray="7 5"':''} marker-end="url(#vis-arrow)"/>`;if(ev.lost)body+=`<text x="${end}" y="${y+5}" fill="${colors.red}" font-size="26">×</text>`;body+=lines(ev.label,Math.max(160,Math.min(440,(a+b)/2)),y+24,48)})}
else if(scene.kind==='bars'){height=scene.rows.length*105+20;let max=Math.max(1,...scene.rows.map(r=>r.segments.reduce((a,s)=>a+s.value,0)));scene.rows.forEach((row,i)=>{let y=30+i*105;body+=lines(row.label,18,y,50,'start');let x=18;row.segments.forEach(s=>{let width=550*s.value/max;if(width>0)body+=`<rect x="${x}" y="${y+12}" width="${width}" height="25" rx="3" fill="${colors[s.tone]||colors.blue}"/>`;x+=width});body+=lines(row.segments.map(s=>s.label).join(' | '),18,y+64,61,'start')})}
else if(scene.kind==='timeline'){height=110+scene.rows.length*125;let total=Math.max(1,scene.total),scale=420/total;body+='<text x="150" y="22">Thời gian (ms) · 0</text><text x="570" y="22" text-anchor="end">'+e(f(total))+' ms</text>';scene.rows.forEach((row,i)=>{let y=55+i*125,x=150+(row.start||0)*scale;body+=lines(row.label,10,y+16,16,'start');if(scene.active===i)body+='<rect x="6" y="'+(y-9)+'" width="585" height="113" rx="8" fill="none" stroke="#df6c24" stroke-width="2"/>';if(row.bitPaths){let tx=row.segments[0].value;body+='<rect x="'+x+'" y="'+y+'" width="'+(tx*scale)+'" height="16" fill="#df6c24"/>';for(let [j,name] of ['first','last'].entries()){let path=row.bitPaths[name],yy=y+35+j*25;body+=lines(j?'Bit cuối':'Bit đầu',10,yy+4,16,'start')+'<path d="M'+(150+path[0]*scale)+' '+yy+'L'+(150+path[1]*scale)+' '+yy+'" stroke="'+(j?'#497657':'#3c7293')+'" stroke-width="3" marker-end="url(#vis-arrow)"/><circle cx="'+(150+path[1]*scale)+'" cy="'+yy+'" r="4" fill="'+(j?'#497657':'#3c7293')+'"/>'}body+=lines('Truyền '+f(tx)+' ms; lan truyền '+f(row.segments[1].value)+' ms',150,y+90,52,'start')}else{for(let seg of row.segments){body+='<rect x="'+x+'" y="'+y+'" width="'+(seg.value*scale)+'" height="24" fill="'+(colors[seg.tone]||colors.blue)+'"/>';x+=seg.value*scale}body+=lines(row.segments.map(seg=>seg.label+' '+f(seg.value)+' ms').join(' · '),150,y+48,52,'start')}});if(scene.markers)body+=lines(scene.markers.map(m=>m.label+': '+f(m.time)+' ms').join(' · '),16,height-22,65,'start')}
else if(scene.kind==='binary'||scene.kind==='ipbits'){let rows=scene.kind==='ipbits'?[{label:'IPv4 · bit 1–16',bits:scene.bits.slice(0,16),offset:0},{label:'IPv4 · bit 17–32',bits:scene.bits.slice(16),offset:16}]:scene.rows;height=rows.length*90+65;rows.forEach((row,j)=>{let y=35+j*90;body+=lines(row.label,18,y,50,'start');[...row.bits].forEach((b,i)=>{let bit=(row.offset||0)+i,col=scene.kind==='ipbits'?bit<scene.parent?colors.orange:bit<scene.prefix?colors.blue:colors.paper:colors.paper,x=18+i*33;body+=`<rect x="${x}" y="${y+12}" width="30" height="32" fill="${col}" stroke="#817b6b"/><text x="${x+15}" y="${y+34}" text-anchor="middle" fill="${col===colors.paper?'#242b25':'#fff'}">${b}</text>`})});body+=lines(scene.kind==='ipbits'?'Cam: network gốc · Xanh: subnet · Sáng: host':'Carry vượt '+(rows[0]?.bits.length||16)+' bit: '+(scene.carry||0),18,height-12,64,'start')}
return svg(body,height,title)}
export function renderTable(table){return table?`<div class="table-wrap vis-table"><table><thead><tr>${table.heads.map(h=>`<th>${e(h)}</th>`).join('')}</tr></thead><tbody>${table.rows.map(row=>`<tr>${row.map(v=>`<td>${e(typeof v==='number'?f(v):v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}
